import{_ as a,b as i,e as t,a6 as o}from"./chunks/framework.CTTTCP0W.js";const g=JSON.parse('{"title":"Using TImage32","description":"","frontmatter":{},"headers":[],"relativePath":"guide/using-timage32.md","filePath":"guide/using-timage32.md","lastUpdated":1787563866000}'),n={name:"guide/using-timage32.md"};function s(r,e,c,h,l,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="using-timage32" tabindex="-1">Using TImage32 <a class="header-anchor" href="#using-timage32" aria-label="Permalink to &quot;Using TImage32&quot;">​</a></h1><p>This section describes the behavior and properties of the <a href="/api/GR32_Image/TCustomImage32">TCustomImage32</a> base class and its derived class, the <a href="/api/GR32_Image/TImage32">TImage32</a> control, as well as their realization of layers.</p><p>Since <code>TCustomImage32</code> and <code>TImage32</code> share the same behavior, we will denote both of them here as <code>TImage32</code>. Most of the description applies to the <code>TImgView32</code> control as well.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>TImage32</code> is an image displaying visual control, which also holds a collection of layers.</p><p>The internal image of the control is a <code>TBitmap32</code> object. The scale and position of the image within the control’s boundaries can be controlled with several properties. See <a href="./UsingTImage32/bitmap-image">Bitmap Image</a> for details.</p><p><code>TImage32</code> maintains a collection of layers. A layer is, generally speaking, an entity which ‘knows’ how to combine itself with the back buffer of the control. See ‘<a href="./UsingTImage32/Using Layers">Using Layers</a>‘ for details.</p><p>When the image paints itself, it runs through several <a href="./UsingTImage32/Paint Stages">Paint Stages</a> which determine the order in which layers and the bitmap image are painted. This order is completely customizeable.</p><p>To avoid flicker and to speed-up scaling and blending operations, each layer and the bitmap image is painted to a back-buffer of the control. See the description of <a href="./repaint-optimization">Repaint Optimization</a> for details on this.</p><p>Finally, <code>TImage32</code> supports change notification via the <a href="/api/GR32_Image/TCustomImage32/Events/OnChange">OnChange</a> event, which is done similar to change notification in <code>TBitmap32</code>. Basically, it redirects change notification from its layers and the bitmap image.</p>',10)])])}const p=a(n,[["render",s]]);export{g as __pageData,p as default};
